package com.tradingplatform.controller; import com.tradingplatform.market.scenario.*; import com.tradingplatform.paper.*; import com.tradingplatform.paper.PaperDtos.*; import com.tradingplatform.persistence.PaperTradeJournalEntity; import java.util.*; import org.springframework.http.*; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/paper") public class PaperTradingController { private final PaperTradingEngine paper; private final ScenarioExecutionService scenarioExecutionService; private final PaperTradeJournalService journalService; private final PaperPerformanceService performanceService; private final PaperPositionMonitorService positionMonitorService; public PaperTradingController(PaperTradingEngine p, ScenarioExecutionService scenarioExecutionService, PaperTradeJournalService journalService, PaperPerformanceService performanceService, PaperPositionMonitorService positionMonitorService){paper=p; this.scenarioExecutionService=scenarioExecutionService; this.journalService=journalService; this.performanceService=performanceService; this.positionMonitorService=positionMonitorService;} @GetMapping("/account") public Account account(){return paper.account();} @PostMapping("/account/reset") public Account reset(){return paper.reset();} @GetMapping("/orders") public List<Order> orders(){return paper.orders();} @PostMapping("/orders") public ResponseEntity<Order> order(@RequestBody OrderRequest request){Order result=paper.submit(request);return result.status()==PaperOrderStatus.FILLED?ResponseEntity.status(HttpStatus.CREATED).body(result):ResponseEntity.unprocessableEntity().body(result);} @PostMapping("/scenario") public ResponseEntity<Map<String,Object>> scenario(@RequestBody ScenarioPaperTradeRequest request){ScenarioExecutionResult result=scenarioExecutionService.execute(request);Map<String,Object> payload=new LinkedHashMap<>();payload.put("status", result.allowed()?"ALLOW":"REJECT");payload.put("scenario", result.scenario().toMap());payload.put("decision", Map.of("status",result.decision().status(),"allowed",result.decision().allowed(),"reasons",result.decision().reasons(),"recommendedSide",result.decision().recommendedSide(),"recommendedSymbol",result.decision().recommendedSymbol()));if(result.order()!=null){payload.put("order", result.order());return ResponseEntity.status(HttpStatus.CREATED).body(payload);}return ResponseEntity.unprocessableEntity().body(payload);} @GetMapping("/positions") public List<Position> positions(){return paper.positions();} @PostMapping("/positions/monitor") public Map<String,Object> monitorPositions(){int updated = positionMonitorService.monitorOpenPositions();return Map.of("status","success","updated",updated);} @GetMapping("/trades") public List<PaperTradeJournalEntity> trades(){return journalService.listTrades();} @GetMapping("/no-trades") public List<PaperTradeJournalEntity> noTrades(){return journalService.listNoTradeEvents();} @GetMapping("/performance") public Map<String,Object> performance(){PaperPerformanceMetrics metrics = performanceService.getPerformance();Map<String,Object> data = new LinkedHashMap<>();data.put("totalTrades", metrics.totalTrades());data.put("openTrades", metrics.openTrades());data.put("closedTrades", metrics.closedTrades());data.put("winningTrades", metrics.winningTrades());data.put("losingTrades", metrics.losingTrades());data.put("winRate", metrics.winRate());data.put("totalGrossPnl", metrics.totalGrossPnl());data.put("totalCharges", metrics.totalCharges());data.put("totalSlippage", metrics.totalSlippage());data.put("totalNetPnl", metrics.totalNetPnl());data.put("averageWin", metrics.averageWin());data.put("averageLoss", metrics.averageLoss());data.put("profitFactor", metrics.profitFactor());data.put("expectancy", metrics.expectancy());data.put("maxDrawdown", metrics.maxDrawdown());data.put("averageHoldingMinutes", metrics.averageHoldingMinutes());data.put("callTrades", metrics.callTrades());data.put("putTrades", metrics.putTrades());data.put("noTradeEvents", metrics.noTradeEvents());return Map.of("status","success","data",data);} @PostMapping("/positions/{id}/close") public ResponseEntity<Order> close(@PathVariable UUID id){Order result=paper.close(id);return result.status()==PaperOrderStatus.FILLED?ResponseEntity.status(HttpStatus.CREATED).body(result):ResponseEntity.unprocessableEntity().body(result);} }
